from lib import *
S = SS('p26')
steps = [
    step("目标是限制在 10 个/秒。做法 A:每个 worker 在请求之间各自 sleep(0.1)(服务器每个请求耗时 0.05 秒)。1 个 worker:100 个请求用了 15.36 秒,平均 6.4 个/秒(sleep 加上请求耗时,比 10 慢);5 个 worker:平均 33.8 个/秒,任意 0.1 秒内最多 5 个;20 个 worker:平均 143.7 个/秒,任意 0.1 秒内最多 20 个。每个 worker 各自 sleep 的速率会随 worker 数线性增长——并不是 10 个/秒。", t=tl(S(1)), done=lidx(S(1), ' 1 个 worker'), mark=lidx(S(1), ' 5 个 worker', '20 个 worker'), b=bars([['1 个 worker:个/秒', 6.4, '6.4'], ['5 个 worker:个/秒', 33.8, '33.8'], ['20 个 worker:个/秒', 143.7, '143.7']], 150, done=[0], mark=[1, 2]), kv=KV([['1 个 worker', '6.4 个/秒'], ['5 个 worker', '33.8 个/秒'], ['20 个 worker', '143.7 个/秒']], ['20 个 worker'])),
    step("做法 B:全局固定间隔(任意两个请求的开始至少隔 0.1 秒,用一把锁排队),不管 1、5、20 个 worker,60 个请求都是 5.90 秒、平均 10.0 个/秒;相邻请求最小间隔 96.9–98.9 ms,中位 100.0 ms;任意 1 秒内最多 11 个(1 秒的窗口两端都算),任意 0.1 秒内最多 2 个。速率与 worker 数无关。", t=tl(S(2)), done=lidx(S(2), ' 1 个 worker', ' 5 个 worker', '20 个 worker'), b=bars([['1 个 worker:个/秒', 10.0, '10.0'], ['5 个 worker:个/秒', 10.0, '10.0'], ['20 个 worker:个/秒', 10.0, '10.0']], 12, done=[0, 1, 2]), kv=KV([['速率', '10.0 个/秒,与 worker 数无关'], ['最小间隔', '约 100 ms'], ['任意 0.1 秒内', '最多 2 个']], ['速率'])),
    step("做法 C:令牌桶 rate=10/秒,桶容量(burst)不同,20 个 worker、100 个请求。burst=1:9.99 秒、9.9 个/秒,最小间隔 99.5 ms,任意 1 秒内最多 10 个(等价于固定间隔);burst=5:9.50 秒、10.4 个/秒,任意 0.1 秒内最多 6 个、任意 1 秒内最多 15 个;burst=20:8.00 秒、12.4 个/秒,任意 0.1 秒内最多 21 个、任意 1 秒内最多 30 个。桶越大,开头越能一口气发出一阵,平均速率也被抬高。", t=tl(S(3)), done=lidx(S(3), 'burst= 1'), mark=lidx(S(3), 'burst= 5', 'burst=20'), b=bars([['burst=1:任意 0.1 秒最多', 2, '2'], ['burst=5', 6, '6'], ['burst=20', 21, '21']], 21, done=[0], mark=[1, 2]), kv=KV([['burst=1', '平滑,等价于固定间隔'], ['burst=5', '0.1 秒内最多 6 个'], ['burst=20', '0.1 秒内最多 21 个']], ['burst=20'])),
    step("令牌桶空闲之后会重新装满:burst=10、rate=10/秒,先发 30 个,停 2 秒,再发 30 个。第一批(桶是满的)前 0.1 秒内发出 11 个、前 0.5 秒内 15 个,30 个用了 2.00 秒;第二批(空闲 2 秒后桶又满了)前 0.1 秒内 11 个、前 0.5 秒内 15 个,用了 1.99 秒。所以“平均 10 个/秒”的限制,在每一次空闲之后仍然允许一次小突发。", t=tl(S(4)), done=lidx(S(4), '第二批'), mark=lidx(S(4), '第一批'), b=bars([['第一批:前 0.1 秒内', 11, '11'], ['第二批:前 0.1 秒内', 11, '11']], 12, mark=[0], done=[1]), kv=KV([['空闲 2 秒后', '桶装满'], ['第二批前 0.1 秒', '又发出 11 个'], ['含义', '平均速率有上限,突发不受限']], ['含义'])),
    step("间隔从哪里算起,速率差很多。服务器耗时 0.05 秒:每个请求完成后再等 0.1 秒,平均 6.4 个/秒(相邻开始间隔中位 156 ms);开始到开始隔 0.1 秒(允许重叠),平均 10.0 个/秒(中位 100 ms)。服务器耗时 0.5 秒:完成后再等 0.1 秒,只有 1.7 个/秒(间隔中位 606 ms);开始到开始隔 0.1 秒仍是 10.0 个/秒。从“完成”算起,速率会被服务器的响应速度拉低;从“开始”算起,才是真正控制了向对方发出的速率。", t=tl(S(5)), done=lidx(S(5), '服务器耗时 0.05 秒', '服务器耗时 0.5 秒'), b=bars([['耗时 0.05 秒:完成后再等 个/秒', 6.4, '6.4'], ['耗时 0.5 秒:完成后再等 个/秒', 1.7, '1.7'], ['开始到开始隔 0.1 秒 个/秒', 10.0, '10.0']], 10, done=[2], mark=[0, 1]), kv=KV([['从完成算起', '速率被响应速度拉低(1.7–6.4 个/秒)'], ['从开始算起', '稳定 10.0 个/秒'], ['区别', '你控制的是发出速率还是处理节奏']], ['区别'])),
]
A = mkartp('p26', 26, '爬虫,限速,令牌桶,速率限制,礼貌,asyncio,Python,真实验证,动画演示',
    '用服务器记录的到达时间量爬虫的限速:每个 worker 各自 sleep(0.1) 时 1、5、20 个 worker 分别是 6.4、33.8、143.7 个/秒;全局固定间隔稳定 10.0 个/秒;令牌桶 burst=20 时任意 0.1 秒内最多 21 个;空闲后桶重新装满再次突发;从完成算起的间隔让速率降到 1.7–6.4 个/秒。',
    '“我加了 sleep,应该很温和了”——如果有 20 个 worker 各自 sleep,对方看到的是 143.7 个/秒。这篇用服务器记录的请求到达时间,把几种限速写法打出的真实节奏量出来:每个 worker 各自睡、全局固定间隔、令牌桶(不同桶容量),以及间隔从完成还是从开始算起。',
    [('143.7 个/秒', '20 个 worker 各自 sleep(0.1) 时服务器实际收到的速率(目标是 10 个/秒)'), ('21', '令牌桶 burst=20、rate=10/秒时,任意 0.1 秒窗口内出现的最大请求数'), ('1.7 个/秒', '服务器耗时 0.5 秒时,“完成后再等 0.1 秒”的实际速率')],
    [('每个 worker 各自 sleep', '<p>在每个 worker 里请求之间 sleep(0.1),速率随 worker 数线性增长:5 个 worker 33.8 个/秒,20 个 143.7 个/秒(1 个 worker 只有 6.4 个/秒,因为还要加上请求耗时)。要限制对一个站点的总速率,limiter 必须是全局共享的。</p>'),
     ('全局固定间隔', '<p>用一把锁让所有请求排队,任意两个请求的开始至少隔 0.1 秒,速率恒定 10.0 个/秒,和 worker 数无关,最小间隔约 100 ms。</p>'),
     ('令牌桶', '<p>令牌桶限制的是平均速率,同时允许桶容量那么大的突发。burst=1 时和固定间隔几乎一样;burst=5 时 0.1 秒内最多 6 个;burst=20 时 0.1 秒内最多 21 个,整体平均速率也高于设定的 10 个/秒(12.4 个/秒,因为开头的突发)。对对方服务器友好,通常把桶设小。</p>'),
     ('空闲之后的突发', '<p>桶在空闲期间会装满:停 2 秒后再发,前 0.1 秒内又出现 11 个请求。“平均速率受限”不等于“任何时刻都平稳”。</p>'),
     ('从哪里算起', '<p>每个请求完成后再等一段时间,速率取决于对方的响应速度(0.05 秒时 6.4 个/秒,0.5 秒时 1.7 个/秒);按开始时间隔开,才能稳定地控制发出速率,并允许请求重叠。哪种更合适取决于你想保护的是对方的什么——这里只量了速率,没有量对方的负载。</p>')],
    steps,
    [ENV_P + '。客户端 aiohttp 3.14.3,worker 从队列里取任务;限速器:固定间隔(asyncio.Lock 加 next 时间)、令牌桶(asyncio.Lock 内循环补充与等待);服务器每个请求耗时 0.05 秒(最后一节也试了 0.5 秒);速率统计取服务器收到请求的时间戳(perf_counter);“任意 1 秒窗口”包含两端,所以恒定 10 个/秒的最大值是 11;每项各跑一次',
     '没有验证:多进程或多机器共用一个限速器(需要共享状态,后面有分布式的文章);对真实站点的影响(对方的限流策略);时钟漂移对长时间运行的限速的影响;按域名分别限速(下一篇之一);漏桶(leaky bucket)与滑动窗口计数器等其它算法;限速与重试叠加后的实际速率'],
    '限速')
